/**
 * Automatic weak-word detection (Phase 2). Pure.
 *
 * A word is weak when the evidence says it is likely to be forgotten or is only
 * half-known. Each signal contributes to a score and, when strong enough, a
 * reason the UI can show ("よく忘れる", "迷いがち", ...).
 */
import type { Competency, QuestionType, WordProgress } from './types.ts';
import { RESPONSE_THRESHOLDS } from './assessment/grading.ts';

export type WeakReason = 'forgetting' | 'low_ease' | 'inaccurate' | 'hesitant' | 'competency_gap';

export const WEAK_REASON_LABELS: Record<WeakReason, string> = {
  forgetting: 'よく忘れる',
  low_ease: '覚えにくい',
  inaccurate: '最近の正答率が低い',
  hesitant: '答えるのに時間がかかる',
  competency_gap: '能力によって差がある',
};

export const WEAK_THRESHOLD = 2;

/** Question type whose timing defines "slow" for each competency. */
const TIMING_TYPE: Partial<Record<Competency, QuestionType>> = {
  recognition: 'en_to_ja_mc',
  recall: 'ja_to_en_mc',
  spelling: 'spelling',
};

export interface Weakness {
  score: number;
  reasons: WeakReason[];
  isWeak: boolean;
  /** Competency with the lowest proficiency, when one clearly lags behind. */
  weakestCompetency: Competency | null;
}

export function detectWeakness(
  p: WordProgress,
  thresholds: Record<QuestionType, readonly [number, number]> = RESPONSE_THRESHOLDS,
): Weakness {
  if (p.reviewCount === 0) return { score: 0, reasons: [], isWeak: false, weakestCompetency: null };
  let score = 0;
  const reasons: WeakReason[] = [];

  if (p.lapses >= 3) {
    score += 2;
    reasons.push('forgetting');
  } else if (p.lapses === 2) {
    score += 1;
    reasons.push('forgetting');
  }

  if (p.easeFactor < 1.8) {
    score += 2;
    reasons.push('low_ease');
  } else if (p.easeFactor < 2.0) {
    score += 0.5;
  }

  const recent = p.recentResults.slice(-6);
  if (recent.length >= 4) {
    const acc = recent.filter(Boolean).length / recent.length;
    if (acc < 0.5) {
      score += 2;
      reasons.push('inaccurate');
    } else if (acc < 0.7) {
      score += 1;
      reasons.push('inaccurate');
    }
  }

  const tested = (Object.keys(p.competencyScores) as Competency[]).filter((c) => (p.competencyScores[c]?.attempts ?? 0) >= 2);
  const hesitant = tested.some((c) => {
    const s = p.competencyScores[c]!;
    const type = TIMING_TYPE[c];
    return type !== undefined && s.attempts >= 3 && s.avgResponseMs > thresholds[type][1];
  });
  if (hesitant) {
    score += 1;
    reasons.push('hesitant');
  }

  let weakestCompetency: Competency | null = null;
  if (tested.length >= 2) {
    const sorted = tested.slice().sort((a, b) => p.competencyScores[a]!.proficiency - p.competencyScores[b]!.proficiency);
    const lo = p.competencyScores[sorted[0]!]!.proficiency;
    const hi = p.competencyScores[sorted[sorted.length - 1]!]!.proficiency;
    if (hi - lo >= 0.45) {
      score += 1;
      reasons.push('competency_gap');
      weakestCompetency = sorted[0]!;
    }
  }

  score = Math.round(score * 100) / 100;
  return { score, reasons, isWeak: score >= WEAK_THRESHOLD, weakestCompetency };
}
